  "bk.biz": "ഇവ നൽകുന്ന ബിസിനസ്",
  "bk.h.biz": "നിങ്ങൾ സേവ് ചെയ്ത ബിസിനസുകളിൽ നിന്ന്. അതിന്റെ GSTIN, വിലാസം, നഗരം, പിൻ കോഡ്, സംസ്ഥാനം എന്നിവ ഓരോ ഡോക്യുമെന്റിലും ചേരും.",
