  "bk.s2": "Excel ടെംപ്ലേറ്റ് പൂരിപ്പിച്ച് ഇവിടെ തിരഞ്ഞെടുക്കുക",
  "bk.tpl": "Excel ടെംപ്ലേറ്റ് ഡൗൺലോഡ്",
  "bk.choose": "നിങ്ങളുടെ Excel അല്ലെങ്കിൽ CSV ഫയൽ തിരഞ്ഞെടുക്കുക",
  "bk.h.s2": "ഒരു ഐറ്റത്തിന് ഒരു വരി. ഒരേ ഇൻവോയ്സ് നമ്പറുള്ള വരികൾ ചേർന്ന് ഒരു ഇൻവോയ്സ് ആകും. നിങ്ങളുടെ സ്വന്തം ഷീറ്റിലെ തലക്കെട്ടുകൾ ഞങ്ങളുടേതിന് സമാനമാണെങ്കിൽ അതും പ്രവർത്തിക്കും.",
  "bk.h.s2e": "ഒരു ഐറ്റത്തിന് ഒരു വരി. ഒരേ ഡോക്യുമെന്റ് നമ്പറുള്ള വരികൾ ചേർന്ന് ഒരു ഇ-വേ ബിൽ ആകും. വാഹനം ഒഴിച്ചിട്ടാൽ Part A മാത്രം ഉണ്ടാകും; വാഹനം പിന്നീട് ചേർക്കാം.",
  "bk.reading": "ഫയൽ വായിക്കുന്നു…",
  "bk.xls": "ഇത് പഴയ .xls ഫയലാണ്. Excel-ൽ File › Save As › Excel Workbook (.xlsx) അല്ലെങ്കിൽ CSV UTF-8 തിരഞ്ഞെടുത്ത്, ആ ഫയൽ ഇവിടെ തിരഞ്ഞെടുക്കുക.",
  "bk.badfile": "ഈ ഫയൽ വായിക്കാനായില്ല. .xlsx അല്ലെങ്കിൽ .csv ഫയൽ തിരഞ്ഞെടുക്കുക.",
  "bk.nohead": "കോളം തലക്കെട്ടുകൾ കണ്ടെത്താനായില്ല (കുറഞ്ഞത് ഡോക്യുമെന്റ് നമ്പറും ഐറ്റവും വേണം). ഞങ്ങളുടെ ടെംപ്ലേറ്റിൽ നിന്ന് തുടങ്ങുക.",
  "bk.none": "ഈ ഫയലിൽ ഡോക്യുമെന്റ് നമ്പറുള്ള വരികളൊന്നും കണ്ടില്ല.",
