  "it.f_pres": "Presumptive scheme",
  "it.f_pres_h": "Business with turnover up to the limit may declare a fixed share of turnover as profit (44AD; 44ADA for professionals). Under the Income-tax Act 2025 this is section 58.",
  "it.p_none": "None: profit as per books",
