  "pr.rates_esi": "വേതനത്തിന്റെ ജീവനക്കാരൻ 0.75%, തൊഴിലുടമ 3.25%, ഓരോന്നും അടുത്ത രൂപയിലേക്ക് റൗണ്ട് അപ്പ് ചെയ്യും (Social Security (Central) Rules, 2026, rule 19). വേതന പരിധി മാസം ₹21,000: ഇപ്പോഴത്തെ പരിധി ESIC സൈറ്റിൽ പരിശോധിക്കുക. ദിവസ വേതനം ₹176 അല്ലെങ്കിൽ അതിൽ കുറവാണെങ്കിൽ ജീവനക്കാരന്റെ വിഹിതം ഇല്ല (ESIC contribution പേജ്).",
