  "pr.pfintro": "മാസത്തെ സാലറി സ്ലിപ്പുകളിൽ നിന്ന് EPFO unified portal-നുള്ള ECR ടെക്സ്റ്റ് ഫയലും ചലാൻ തുകകളും ഉണ്ടാക്കും. ആദ്യം സ്ലിപ്പുകൾ ഉണ്ടാക്കുക (സാലറി ടാബ്); സ്ലിപ്പ് ഇല്ലാത്ത ജീവനക്കാരെ താഴെ കാണിക്കും.",
  "pr.unver_pf": "അപ്ലോഡ് ചെയ്യുന്നതിന് മുമ്പ് പരിശോധിക്കുക: ഇത് ഉണ്ടാക്കിയപ്പോൾ (14 Nov 2026) EPFO-യുടെ സ്വന്തം ഫയൽ ഘടനാ ഡോക്യുമെന്റ് തുറക്കാൻ കഴിഞ്ഞില്ല. 11 ഫീൽഡുകളും അവയുടെ ക്രമവും പേറോൾ സോഫ്റ്റ്വെയർ നിർമ്മാതാക്കൾ പ്രസിദ്ധീകരിക്കുന്നതനുസരിച്ചാണ്. ഫയൽ EPFO പോർട്ടലിന്റെ ECR പേജിൽ അപ്ലോഡ് ചെയ്യുക; പോർട്ടൽ ഒരു വരി നിരസിച്ചാൽ കാരണം പറയും.",
