  "it.f_turn": "വർഷത്തെ ടേണോവർ അല്ലെങ്കിൽ വരവുകൾ",
  "it.f_turn_h": "നിങ്ങളുടെ കണക്കുകളിൽ നിന്ന്, മുഴുവൻ വർഷത്തേക്ക് നീട്ടിയത്: {n}.",
  "it.f_dig_h": "44AD ഈ വരവുകൾക്ക് 6%-ഉം ബാക്കിയുള്ളതിന് 8%-ഉം ഉപയോഗിക്കുന്നു. തുക ടൈപ്പ് ചെയ്യുക.",
  "it.f_bus": "വർഷത്തെ ബിസിനസ് അല്ലെങ്കിൽ പ്രൊഫഷണൽ വരുമാനം",
  "it.f_bus_h": "ഇതുവരെയുള്ള കണക്കുകൾ ({d} വരെ): {so}. മുഴുവൻ വർഷത്തേക്ക് നീട്ടിയത്: {y}. പ്രിസംപ്റ്റീവ് സ്കീം തിരഞ്ഞെടുത്താൽ ഇത് പരിഗണിക്കില്ല.",
  "it.f_oth": "മറ്റ് സ്രോതസ്സുകളിൽ നിന്നുള്ള വരുമാനം",
  "it.f_oth_h": "പലിശ, മറ്റുള്ളവരിൽ നിന്നുള്ള വാടക, നിങ്ങളുടെ കണക്കുകളിൽ മറ്റ് വരുമാനമായി രേഖപ്പെടുത്തിയ സമാന വരുമാനം, മുഴുവൻ വർഷത്തേക്ക് നീട്ടിയത്.",
  "it.f_sal": "സാലറി അല്ലെങ്കിൽ പെൻഷൻ",
  "it.f_sal_h": "സ്റ്റാൻഡേർഡ് ഡിഡക്ഷന് മുമ്പ്.",
  "it.f_house": "വീട്ടു സ്വത്തിൽ നിന്നുള്ള വരുമാനം",
  "it.f_house_h": "സ്റ്റാൻഡേർഡ് ഡിഡക്ഷനും ഹോം ലോൺ പലിശയും കുറച്ചത്; നഷ്ടം മൈനസ് ചിഹ്നത്തോടെ ടൈപ്പ് ചെയ്യുക.",
  "it.f_cg": "സാധാരണ റേറ്റിലുള്ള ക്യാപിറ്റൽ ഗെയിൻസ്",
  "it.f_cg_h": "പ്രത്യേക റേറ്റിൽ ടാക്സുള്ള ലാഭങ്ങൾ (ഷെയറുകൾ, ഇക്വിറ്റി ഫണ്ടുകൾ, പ്രോപ്പർട്ടി) ഇവിടെ കണക്കാക്കുന്നില്ല.",
  "it.f_80c": "പഴയ റെജീം: 80C തരം ഡിഡക്ഷനുകൾ",
  "it.f_80c_h": "PF, ലൈഫ് ഇൻഷുറൻസ്, ടാക്സ് സേവിംഗ് ഫണ്ടുകൾ തുടങ്ങിയവ; പരമാവധി ₹1,50,000. Income-tax Act 2025-ൽ Section 123.",
  "it.f_dedo": "പഴയ റെജീം: മറ്റ് ഡിഡക്ഷനുകൾ",
  "it.f_dedo_h": "ഹെൽത്ത് ഇൻഷുറൻസ്, സ്വന്തം താമസ വീടിന്റെ ഹോം ലോൺ പലിശ, NPS അധികം തുടങ്ങിയവ, നിങ്ങൾ കൂട്ടിയത്.",
  "it.f_nps": "തൊഴിലുടമയുടെ NPS വിഹിതം",
  "it.f_nps_h": "രണ്ട് റെജീമിലും അനുവദിക്കും; തുക ടൈപ്പ് ചെയ്യുക.",
  "it.f_sur": "സർചാർജ്",
  "it.f_sur_h": "കണക്കാക്കുന്നില്ല. നിങ്ങളുടെ വരുമാനം ₹50 ലക്ഷത്തിന് മുകളിലാണെങ്കിൽ തുക ടൈപ്പ് ചെയ്യുക.",
  "it.f_tds": "ഈ വരുമാനത്തിൽ കുറച്ച TDS, TCS",
  "it.f_tds_h": "വർഷത്തെ നിങ്ങളുടെ വരവുകളിലും മറ്റ് വരുമാനത്തിലും രേഖപ്പെടുത്തിയ TDS-ൽ നിന്ന് തുടങ്ങുന്നു. ഇനിയും കുറയ്ക്കാനുള്ളത് കൂട്ടുക.",
  "it.f_def": "പിന്നീട് വരുന്ന ലാഭത്തിലെ ടാക്സ്",
  "it.f_mon": "ടാക്സ് കുറവാണെങ്കിൽ പലിശയുടെ മാസങ്ങൾ",
  "it.f_mon_h": "വർഷത്തിന് ശേഷമുള്ള 1 April മുതൽ റിട്ടേൺ പ്രോസസ് ചെയ്യുന്ന ദിവസം വരെ. 4 = 31 July-ക്കകം ഫയൽ ചെയ്ത റിട്ടേൺ.",
  "it.m_senior": "ബിസിനസ് അല്ലെങ്കിൽ പ്രൊഫഷണൽ വരുമാനമില്ലാത്ത 60 വയസ്സോ അതിൽ കൂടുതലോ ഉള്ള റെസിഡന്റ് അഡ്വാൻസ് ടാക്സ് അടയ്ക്കേണ്ടതില്ല (section 403(3)). റിട്ടേൺ ഫയൽ ചെയ്യുമ്പോൾ ബാക്കി അടയ്ക്കുക.",
  "it.m_below": "TDS കഴിഞ്ഞുള്ള ടാക്സ് {n} ആണ്, ₹10,000-ൽ താഴെ, അതുകൊണ്ട് അഡ്വാൻസ് ടാക്സ് വേണ്ട (section 404). റിട്ടേൺ ഫയൽ ചെയ്യുമ്പോൾ ബാക്കി അടയ്ക്കുക.",
  "it.m_pres": "പ്രിസംപ്റ്റീവ് സ്കീമിൽ അഡ്വാൻസ് ടാക്സ് മുഴുവനും 15 March-നോ അതിനു മുമ്പോ അടയ്ക്കണം (section 408(2)).",
  "it.m_sur": "നിങ്ങളുടെ വരുമാനം ₹50 ലക്ഷത്തിന് മുകളിലാണ്: സർചാർജ് ടൈപ്പ് ചെയ്യുക, അത് ഇവിടെ കണക്കാക്കുന്നില്ല.",
  "it.m_past": "ഈ വർഷം കഴിഞ്ഞു. 31 March-ന് ശേഷം അടച്ച അഡ്വാൻസ് ടാക്സ് ഈ വർഷത്തെ അഡ്വാൻസ് ടാക്സായി കണക്കാക്കില്ല; കുറവിന് എത്ര ചെലവാകും എന്ന് താഴെയുള്ള പലിശ കാണിക്കുന്നു.",
  "it.m_season": "എസ്റ്റിമേറ്റ് ഇതുവരെയുള്ള ലാഭം നേർരേഖയിൽ മുഴുവൻ വർഷത്തേക്ക് നീട്ടുന്നു. നിങ്ങളുടെ ബിസിനസ് സീസണൽ ആണെങ്കിൽ വർഷത്തേക്കുള്ള നിങ്ങളുടെ സ്വന്തം കണക്ക് ടൈപ്പ് ചെയ്യുക.",
