  "it.csv": "Excel (CSV)",
  "it.print": "പ്രിന്റ്",
  "it.basis": "ഈ കണക്കുകൾ എന്തിനെ അടിസ്ഥാനമാക്കിയാണ് ({d} പ്രകാരം)",
  "it.b1": "റേറ്റുകൾ ({d} പ്രകാരം), ടാക്സ് വർഷം 2026-27: പുതിയ റെജീം ₹4 ലക്ഷം വരെ ഇല്ല, ₹8 ലക്ഷം വരെ 5%, ₹12 ലക്ഷം വരെ 10%, ₹16 ലക്ഷം വരെ 15%, ₹20 ലക്ഷം വരെ 20%, ₹24 ലക്ഷം വരെ 25%, അതിനു മുകളിൽ 30%; ₹12 ലക്ഷം വരെ വരുമാനത്തിന് ടാക്സ് ഇല്ലാത്ത വിധം റിബേറ്റ്, അതിനു തൊട്ടുമുകളിൽ മാർജിനൽ റിലീഫ്; സാലറിക്ക് സ്റ്റാൻഡേർഡ് ഡിഡക്ഷൻ ₹75,000. പഴയ റെജീം: ₹2.5 ലക്ഷം വരെ ഇല്ല (60-ൽ ₹3 ലക്ഷം, 80-ൽ ₹5 ലക്ഷം), ₹5 ലക്ഷം വരെ 5%, ₹10 ലക്ഷം വരെ 20%, അതിനു മുകളിൽ 30%; ₹5 ലക്ഷം വരെ റിബേറ്റ് ₹12,500; സ്റ്റാൻഡേർഡ് ഡിഡക്ഷൻ ₹50,000. സാലറി സ്ലിപ്പ് ടൂൾ ഇതിനകം ഉപയോഗിക്കുന്ന റേറ്റുകളാണ് ഇവ; ഈ ബിൽഡിൽ Finance Act-ൽ നിന്ന് വീണ്ടും വായിച്ചിട്ടില്ല, അതുകൊണ്ട് പരിശോധിക്കുക.",
  "it.b2": "അഡ്വാൻസ് ടാക്സ് (Income-tax Act 2025, sections 403 to 408): TDS കഴിഞ്ഞുള്ള ടാക്സ് ₹10,000 അല്ലെങ്കിൽ അതിൽ കൂടുതലാണെങ്കിൽ അടയ്ക്കണം; 15 June-നകം 15%, 15 September-നകം 45%, 15 December-നകം 75%, 15 March-നകം മുഴുവനും; പ്രിസംപ്റ്റീവ് ടാക്സ്പേയർ 15 March-നകം മുഴുവനും അടയ്ക്കുന്നു; 31 March വരെയുള്ള പേയ്മെന്റ് ആ വർഷത്തേക്ക് കണക്കാക്കും; ബിസിനസ് വരുമാനമില്ലാത്ത 60 വയസ്സോ അതിൽ കൂടുതലോ ഉള്ള റെസിഡന്റിന് ഒഴിവുണ്ട്.",
  "it.b3": "പലിശ: ടാക്സിന്റെ 90%-ൽ കുറവ് അടച്ചാൽ section 424 (പഴയ 234B) കുറവിന് മാസത്തിനോ മാസത്തിന്റെ ഭാഗത്തിനോ 1% ആണ്; section 425 (പഴയ 234C) ആദ്യ മൂന്ന് ഗഡുക്കളിൽ ഓരോന്നിന്റെയും കുറവിന് 3% (15 June-നകം 12%-ഉം 15 September-നകം 36%-ഉം അടച്ചാൽ ഇല്ല), March-ലെ കുറവിന് 1%.",
  "it.b5": "ബുക്ക് പ്രോഫിറ്റ് ടാക്സബിൾ പ്രോഫിറ്റ് അല്ല: ആക്ട് പ്രകാരമുള്ള ഡിപ്രിസിയേഷൻ, അനുവദിക്കാത്ത ചെലവുകൾ, പ്രിസംപ്റ്റീവ് നിയമങ്ങൾ എന്നിവ അത് മാറ്റും. ഈ പ്ലാനും ഡാറ്റ ഷീറ്റും നിങ്ങളുടെ അക്കൗണ്ടന്റിന് കൊടുക്കുക.",
  "it.b6": "കണക്കാക്കാത്തവ: സർചാർജ്, പ്രത്യേക റേറ്റിലുള്ള ക്യാപിറ്റൽ ഗെയിൻസ്, വിദേശ ടാക്സ് റിലീഫ്, മൈനറുടെ വരുമാനത്തിലെ ടാക്സ്, വൈകി ഫയൽ ചെയ്യുന്നതിലെ പലിശ.",
  "it.b7": "ഒന്നും ഫയൽ ചെയ്യുന്നില്ല, നിങ്ങളുടെ കണക്കുകളിൽ ഒന്നും പോസ്റ്റ് ചെയ്യുന്നില്ല.",
  "it.itr_h": "ഏത് റിട്ടേൺ ഫോം യോജിക്കും, എന്തുകൊണ്ട്, ഏതൊക്കെ പേപ്പറുകൾ തയ്യാറാക്കി വയ്ക്കണം എന്ന് കാണാൻ കുറച്ച് ചോദ്യങ്ങൾക്ക് ഉത്തരം നൽകുക.",
  "it.use_form": "യോജിക്കുന്ന ITR ഫോം: {f}",
