  "bi.starth": "നെറ്റ് ബാങ്കിംഗിൽ നിന്ന് ഡൗൺലോഡ് ചെയ്ത CSV അല്ലെങ്കിൽ Excel സ്റ്റേറ്റ്മെന്റ് തുറക്കുക. ഓരോ വരിയും നിങ്ങളുടെ പാർട്ടികൾ, ഓപ്പൺ ബില്ലുകൾ, ചെലവ് ഹെഡുകൾ എന്നിവയുമായി ഒത്തുനോക്കും; നിങ്ങൾ പരിശോധിച്ച് എല്ലാം ഒറ്റയടിക്ക് പോസ്റ്റ് ചെയ്യുക.",
