  "nav.ca": "അക്കൗണ്ടന്റ് വ്യൂവർ",
  "ca.mk": "എന്റെ അക്കൗണ്ടന്റിന് ഒരു ഫയൽ ഉണ്ടാക്കുക (റീഡ്-ഓൺലി)",
  "ca.t": "എന്റെ അക്കൗണ്ടന്റിനുള്ള ഫയൽ",
  "ca.intro": "ഒരു ബിസിനസും കാലയളവും ഒരൊറ്റ റീഡ്-ഓൺലി ഫയലിലാക്കുന്നു (.nsca). അത് WhatsApp അല്ലെങ്കിൽ ഇമെയിൽ വഴി നിങ്ങളുടെ അക്കൗണ്ടന്റിന് അയയ്ക്കുക. അവർ അത് ca.niveshsahayak.in-ൽ തുറന്ന് കണക്കുകൾ വായിച്ച്, ചോദ്യങ്ങൾ ചേർത്ത്, കമന്റുകൾ നിങ്ങൾക്ക് തിരികെ അയയ്ക്കും.",
  "ca.notlive": "ഇത് ഫയൽ കൈമാറ്റമാണ്, ലൈവ് ആയി പങ്കിട്ട ലോഗിൻ അല്ല. ഫയൽ ഉണ്ടാക്കിയ സമയത്തെ കണക്കുകളാണ് നിങ്ങളുടെ അക്കൗണ്ടന്റ് കാണുന്നത്. ലൈവ് ലോഗിന് നിങ്ങളുടെ കണക്കുകൾ സൂക്ഷിക്കുന്ന ഒരു സെർവർ വേണം, Nivesh Sahayak-ന് അതില്ല: നിങ്ങളുടെ കണക്കുകൾ നിങ്ങളുടെ ഡിവൈസിൽ തന്നെ. പുതിയ എൻട്രികൾക്ക് പുതിയ ഫയൽ ഉണ്ടാക്കുക.",
  "ca.what": "എന്തൊക്കെ ഉൾപ്പെടും",
  "ca.earlier": "ആദ്യ തീയതിക്ക് മുമ്പുള്ള എൻട്രികളും (ഓപ്പണിംഗ് ബാലൻസുകൾക്കും ഏജിംഗിനും വേണം)",
  "ca.items": "പർച്ചേസ്, സെയിൽ റേറ്റുകളോടെ ഐറ്റം ലിസ്റ്റ് (സ്റ്റോക്കിന് വേണം)",
  "ca.extra": "ടിക് ചെയ്താൽ മാത്രം",
  "ca.extrah": "ടിക് ചെയ്തില്ലെങ്കിൽ ഒഴിവാക്കും. ചിത്രങ്ങൾ (ലോഗോ, ഒപ്പ്), നിങ്ങളുടെ PIN, ബാക്കപ്പ് സെറ്റിംഗുകൾ ഒരിക്കലും ഉൾപ്പെടുത്തില്ല.",
  "ca.orders": "ക്വട്ടേഷനുകൾ, പ്രോഫോർമ ഇൻവോയ്സുകൾ, സെയിൽസ് ഓർഡറുകൾ, ചലാനുകൾ, പർച്ചേസ് ഓർഡറുകൾ",
  "ca.staff": "സാലറി സ്ലിപ്പുകൾ, സ്റ്റാഫ് അഡ്വാൻസുകൾ, ലോണുകളും EMI-കളും, പെറ്റി ക്യാഷ്, ജീവനക്കാരുടെ ലിസ്റ്റ്",
  "ca.phones": "പാർട്ടികളുടെ ഫോൺ നമ്പറുകൾ, ഇമെയിൽ വിലാസങ്ങൾ, WhatsApp നമ്പറുകൾ",
