  "ca.msg": "{biz}-ന്റെ {from} മുതൽ {to} വരെയുള്ള കണക്കുകൾ. ഒപ്പമുള്ള ഫയൽ {url}-ൽ തുറക്കുക (ലോഗിൻ വേണ്ട, ഒന്നും അപ്ലോഡ് ചെയ്യുന്നില്ല). ചെക്ക് കോഡ്: {code}. ഇത് ഇന്ന് ഉണ്ടാക്കിയ റീഡ്-ഓൺലി കോപ്പിയാണ്; നിങ്ങളുടെ ചോദ്യങ്ങൾ ഒരു കമന്റ് ഫയലായി തിരികെ അയയ്ക്കുക.",
  "ca.how": "ഫയൽ WhatsApp അല്ലെങ്കിൽ ഇമെയിൽ വഴി അറ്റാച്ച്മെന്റായി അയയ്ക്കുക. WhatsApp പേരിന്റെ അവസാനം .nsca കാണിക്കുന്നുണ്ടെങ്കിൽ പേര് മാറ്റരുത്.",
  "ca.cT": "CA കമന്റുകൾ",
  "ca.cIntro": "നിങ്ങളുടെ അക്കൗണ്ടന്റ് ചോദ്യങ്ങളും കമന്റുകളും ഉള്ള ഒരു ചെറിയ ഫയൽ (.nsca-comments) തിരികെ അയയ്ക്കും. ഓരോ ചോദ്യവും ബന്ധപ്പെട്ട എൻട്രിയുടെ അടുത്ത് കാണാൻ അത് ഇവിടെ ലോഡ് ചെയ്യുക. മറുപടി നൽകുക, ക്ലോസ് ചെയ്തതായി മാർക്ക് ചെയ്യുക, ഫയൽ വീണ്ടും സേവ് ചെയ്ത് തിരികെ അയയ്ക്കുക.",
