  "cv.h1": "അക്കൗണ്ടന്റ് വ്യൂവർ: നിങ്ങളുടെ ക്ലയന്റ് അയച്ച കണക്കു ഫയൽ തുറക്കുക",
  "cv.intro": "നിങ്ങളുടെ ക്ലയന്റ് ഒരു കാലയളവിലെ കണക്കുകൾ ഒരു ഫയലിലാക്കി WhatsApp-ലോ ഇമെയിലിലോ നിങ്ങൾക്ക് അയയ്ക്കുന്നു. അത് ഇവിടെ തുറന്ന് വായിക്കുക: കുടിശ്ശിക, പാർട്ടികൾ, ലെഡ്ജറുകൾ, ഡേ ബുക്ക്, GST കണക്ക്, ഫൈനൽ അക്കൗണ്ട്സ്, എല്ലാ ഡോക്യുമെന്റുകളും. തിരയുക, ഫിൽട്ടർ ചെയ്യുക, ഏത് എൻട്രിയിലും ചോദ്യം ചോദിക്കുക, നിങ്ങളുടെ കമന്റുകൾ ഒരു ചെറിയ ഫയലായി തിരികെ അയയ്ക്കുക. സൗജന്യം, ലോഗിൻ വേണ്ട, ഒന്നും അപ്ലോഡ് ചെയ്യുന്നില്ല: ഫയൽ നിങ്ങളുടെ ബ്രൗസറിനുള്ളിൽ വായിക്കുന്നു.",
