  "cv.cT": "ചോദ്യങ്ങളും കമന്റുകളും",
  "cv.how.h": "ഇത് എങ്ങനെ പ്രവർത്തിക്കുന്നു",
  "cv.how.1": "നിങ്ങളുടെ ക്ലയന്റ് Nivesh Sahayak തുറന്ന്, എന്റെ ഡാറ്റ, നിങ്ങളുടെ അക്കൗണ്ടന്റിന് അയയ്ക്കുക എന്നതിൽ പോയി, ഒരു ബിസിനസിനും കാലയളവിനും “എന്റെ അക്കൗണ്ടന്റിന് ഒരു ഫയൽ ഉണ്ടാക്കുക” തിരഞ്ഞെടുക്കുന്നു.",
  "cv.how.2": "അവർ ഫയലും (.nsca-യിൽ അവസാനിക്കുന്നത്) ഒരു ചെറിയ ചെക്ക് കോഡും ഒരേ മെസേജിൽ നിങ്ങൾക്ക് അയയ്ക്കുന്നു.",
  "cv.how.3": "നിങ്ങൾ ഈ പേജിൽ ഫയൽ തുറക്കുന്നു. ഫയൽ മാറ്റമില്ലാത്തതാണോ എന്ന് പേജ് പറയും, ഒത്തുനോക്കാൻ ക്ലയന്റ് തന്ന ചെക്ക് കോഡ് ടൈപ്പ് ചെയ്യാനും അനുവദിക്കും.",
  "cv.how.4": "കണക്കുകൾ വായിക്കുക, തിരയുക, ഏത് ഡോക്യുമെന്റിലും ഡേ ബുക്ക് എൻട്രിയിലും സ്ക്രീനിലും “ഒരു ചോദ്യമോ കമന്റോ ചേർക്കുക” അമർത്തുക. നിങ്ങൾ എഴുതുന്നതെല്ലാം ഈ ബ്രൗസറിൽ തന്നെ നിൽക്കും.",
  "cv.how.5": "കഴിഞ്ഞാൽ, “ചോദ്യങ്ങളും കമന്റുകളും” തുറന്ന് ചെറിയ .nsca-comments ഫയൽ തിരികെ അയയ്ക്കുക. നിങ്ങളുടെ ക്ലയന്റ് അത് ലോഡ് ചെയ്ത് ഓരോ ചോദ്യവും എൻട്രിയുടെ അടുത്ത് കാണും. അവർക്ക് മറുപടി നൽകാം, മറുപടികൾ നിങ്ങൾക്ക് ഇവിടെ ലോഡ് ചെയ്യാം.",
  "cv.live.h": "ഫയൽ കൈമാറ്റം, ലൈവ് ലോഗിൻ അല്ല",
  "cv.live.p": "ഇത് ഒരു ഫയൽ കൈമാറ്റമാണ്. നിങ്ങൾ ക്ലയന്റിന്റെ അക്കൗണ്ടിൽ ലോഗിൻ ചെയ്യുന്നില്ല, അവർ പിന്നീട് വരുത്തുന്ന മാറ്റങ്ങൾ കാണുന്നുമില്ല. ലൈവ് ആയി പങ്കിട്ട ലോഗിന് കണക്കുകൾ സൂക്ഷിക്കുന്ന ഒരു സെർവർ വേണം, Nivesh Sahayak-ന് അതില്ല: കണക്കുകൾ ക്ലയന്റിന്റെ ഡിവൈസിൽ തന്നെ. പുതിയ കാലയളവിനോ തിരുത്തലുകൾക്ക് ശേഷമോ ക്ലയന്റിനോട് പുതിയ ഫയൽ ചോദിക്കുക.",
  "cv.safe.h": "ഫയലിൽ എന്താണ് ഉള്ളത്, എന്താണ് ഇല്ലാത്തത്",
  "cv.safe.p": "എന്തൊക്കെ ഉൾപ്പെടുത്തണം എന്ന് നിങ്ങളുടെ ക്ലയന്റ് ടിക് ചെയ്യുന്നു. സാധാരണ ഫയലിൽ ഒരു ബിസിനസിന്റെ കാലയളവ് അവസാനം വരെയുള്ള എൻട്രികൾ, പാർട്ടികൾ, ഐറ്റങ്ങൾ എന്നിവ ഉണ്ടാകും. ക്വട്ടേഷനുകളും ഓർഡറുകളും, സാലറി, സ്റ്റാഫ് റെക്കോർഡുകൾ, ഫോൺ നമ്പറുകളും ഇമെയിൽ വിലാസങ്ങളും, ബിസിനസിന്റെ ബാങ്ക് അക്കൗണ്ട് വിവരങ്ങളും ക്ലയന്റ് ടിക് ചെയ്തില്ലെങ്കിൽ ഒഴിവാക്കും. ചിത്രങ്ങൾ, PIN, ബാക്കപ്പ് സെറ്റിംഗുകൾ ഒരിക്കലും ഉൾപ്പെടുത്തില്ല. ഫയലിൽ ഒരു ചെക്ക്സം ഉണ്ട്, അതുകൊണ്ട് അതിലെ ഏത് മാറ്റവും ഈ പേജിൽ കാണിക്കും. ഫയൽ എഡിറ്റ് ചെയ്ത് ചെക്ക്സം വീണ്ടും കണക്കാക്കുന്ന ഒരാളെ ചെക്ക്സത്തിന് തടയാൻ കഴിയില്ല, അതുകൊണ്ട് ക്ലയന്റ് വേറെ അയച്ച ചെക്ക് കോഡുമായി ഒത്തുനോക്കുക.",
  "cv.readonly": "ഇത് ഒരു ഫയലിന്റെ റീഡ്-ഓൺലി കാഴ്ചയാണ്: ഇവിടെ ഒന്നും മാറ്റാനോ സേവ് ചെയ്യാനോ കഴിയില്ല.",
  "cv.notfile": "ഇത് Nivesh Sahayak അക്കൗണ്ടന്റ് ഫയൽ (.nsca) അല്ല.",
  "cv.iscomments": "ഇത് ഒരു കമന്റ് ഫയലാണ്. ആദ്യം കണക്കു ഫയൽ (.nsca) തുറക്കുക, പിന്നെ “ചോദ്യങ്ങളും കമന്റുകളും” എന്നതിൽ നിന്ന് കമന്റുകൾ ലോഡ് ചെയ്യുക.",
  "cv.newer": "ഈ ഫയൽ ഒരു പുതിയ പതിപ്പിൽ ഉണ്ടാക്കിയതാണ്. ഈ പേജ് റീലോഡ് ചെയ്ത് വീണ്ടും ശ്രമിക്കുക.",
  "cv.nostore": "നിങ്ങളുടെ കമന്റുകൾ ഈ ബ്രൗസറിൽ സൂക്ഷിക്കാൻ കഴിഞ്ഞില്ല. ഇപ്പോൾ തന്നെ കമന്റ് ഫയൽ സേവ് ചെയ്യുക.",
