  "cv.sumbad": "ഫയൽ അതിന്റെ ചെക്ക്സവുമായി ഒത്തുപോകുന്നില്ല.",
  "cv.sumbadh": "ഉണ്ടാക്കിയ ശേഷം ഇത് മാറ്റുകയോ കേടാവുകയോ ചെയ്തു. ആശ്രയിക്കുന്നതിന് മുമ്പ് ക്ലയന്റിനോട് വീണ്ടും അയയ്ക്കാൻ പറയുക.",
