  "cv.cIntro": "നിങ്ങളുടെ ചോദ്യങ്ങളും കമന്റുകളും. ഈ ഫയലിനായി ഇവ ഈ ബ്രൗസറിൽ സൂക്ഷിക്കും. “കമന്റ് ഫയൽ സേവ് ചെയ്യുക” അമർത്തി ക്ലയന്റിന് അയയ്ക്കുക; അവർ അത് ലോഡ് ചെയ്ത് ഓരോ ചോദ്യവും എൻട്രിയുടെ അടുത്ത് കാണും.",
