  "cv.dayh": "ഓരോ എൻട്രിയും തീയതി ക്രമത്തിൽ, അത് ബാധിക്കുന്ന അക്കൗണ്ടുകളോടെ. ഒരു എൻട്രിയെക്കുറിച്ച് ചോദിക്കാൻ സ്പീച്ച് ബബിൾ ഉപയോഗിക്കുക.",
  "cv.gsth": "കണക്കുകളിലെ അതേ എൻട്രികളിൽ നിന്ന് മാസം തോറും: ടാക്സബിൾ സെയിൽസ് (ക്രെഡിറ്റ് നോട്ടുകൾ കുറച്ചത്), ഔട്ട്പുട്ട് ടാക്സ്, പർച്ചേസുകളിലും ചെലവുകളിലുമുള്ള ഇൻപുട്ട് ടാക്സ് ക്രെഡിറ്റ്, നെറ്റ് തുക.",
  "cv.gstnote": "റിട്ടേണുകളുമായി ഒത്തുനോക്കാനുള്ള ഒരു കണക്ക് മാത്രം, റിട്ടേണുകൾ അല്ല. റിവേഴ്സ് ചാർജ്, അഡ്വാൻസുകൾ, സെറ്റ്-ഓഫ് എന്നിവ കണക്കുകളിൽ ഉണ്ട്, പക്ഷേ ഇവിടെ വേർതിരിച്ചിട്ടില്ല.",
