  "pk.limit": "ഒരു പാക്ക് ചേർക്കുക മാത്രമേ ചെയ്യൂ. നിങ്ങൾ ഇതിനകം സേവ് ചെയ്തത് ഒരിക്കലും ഡിലീറ്റ് ചെയ്യുകയോ മാറ്റുകയോ ഇല്ല: ഒരേ പേരുള്ള ഐറ്റം ഒഴിവാക്കും, നിങ്ങൾ ഇതിനകം പൂരിപ്പിച്ച സെറ്റിംഗ് നിലനിർത്തും, ഒന്നും ഓഫ് ചെയ്യില്ല. വിൽപന വിലകൾ നിങ്ങൾക്ക് ടൈപ്പ് ചെയ്യാൻ ശൂന്യമായി വിടും. ഐറ്റം പേരുകളും കുറിപ്പുകളും ഇംഗ്ലീഷിലാണ്.",
