  "cap.intro": "സപ്ലയറുടെ ബില്ലിന്റെ ഫോട്ടോ എടുക്കുക അല്ലെങ്കിൽ തിരഞ്ഞെടുക്കുക. ടെക്സ്റ്റ് ഈ ഡിവൈസിൽ തന്നെ വായിക്കും, ഫോട്ടോ എവിടേക്കും അയയ്ക്കുന്നില്ല. ഒന്നും സേവ് ചെയ്യുന്നതിന് മുമ്പ് നിങ്ങൾ ഓരോ ഫീൽഡും പരിശോധിക്കും.",
