/* Lines changed on 15 Nov 2026 (ESI template, income-tax source) */
NS.addLang("ml", {
  "pr.e_lastday": "ഈ റീസൺ കോഡിന് ജോലിയുടെ അവസാന ദിവസം വേണം",
  "pr.unver_esi": "ഈ ഷീറ്റ് ESIC പോർട്ടലിന്റെ സ്വന്തം Monthly Contribution ടെംപ്ലേറ്റ് പോലെയാണ് (2026 നവംബർ 15-ന് പരിശോധിച്ചു): ആറ് കോളങ്ങൾ ടെക്സ്റ്റായി, Excel 97-2003 (.xls) ഫയൽ. ഈ മാസം ശമ്പളം കിട്ടാത്ത ജീവനക്കാരും റീസൺ കോഡോടെ ലിസ്റ്റിൽ വരും. ആദ്യം ഒരു മാസം അപ്‌ലോഡ് ചെയ്ത് പോർട്ടലിന്റെ ഫലം നോക്കുക.",
  "it.b4": "മുകളിലെ സെക്ഷനുകൾ 2026 നവംബർ 15-ന് ആദായനികുതി വകുപ്പിന്റെ വെബ്സൈറ്റിലെ (incometaxindia.gov.in) ഔദ്യോഗിക വാചകവുമായി വാക്കിന് വാക്ക് ഒത്തുനോക്കി. അച്ചടിച്ച നിയമമാണ് അന്തിമം.",
  "it.f_def_h": "ഇനിയും നേടാത്ത ക്യാപിറ്റൽ ഗെയിൻ, സമ്മാനം/ലോട്ടറി വിജയം, ഡിവിഡന്റ് അല്ലെങ്കിൽ ആദ്യ വർഷത്തെ ബിസിനസ് ലാഭം: ബാക്കി തവണകളിൽ അടച്ചാൽ മുൻ തവണകളിൽ കണക്കാക്കില്ല (സെക്ഷൻ 425(4))."
});

