  "app.ab.12": "My day: ഇന്ന് ശ്രദ്ധിക്കേണ്ടവ, മാസാവസാന ചെക്ക്‌ലിസ്റ്റ്, ബിസിനസ് ഹെൽത്ത് സ്കോർ, റിമൈൻഡറുകൾ, കൂടാതെ ക്ലിനിക്, സലൂൺ, ഹോട്ടൽ, വാടക, ഗാരേജ്, ജ്വല്ലറി, മണ്ടി, പെട്രോൾ പമ്പ് തുടങ്ങിയവയ്ക്ക് തയ്യാറായ ടൂളുകൾ."
